// Intent Finder already returns one entry per DISTINCT process needed (deduplicated
// there, not once per record) -- this just turns that array field into one n8n item per
// entry so the shared resolution loop below can process each via a real Execute Workflow
// call, which only ever forwards the first item it's handed when given several.
const { processes, ...base } = $json;
return (processes || []).map((p) => ({ json: {
  ...base,
  path: p.path,
  process_name: p.process_name,
  items: [],
} }));

// Execute Workflow replaces the item's json entirely with schema-resolution.json's own
// return value -- path/process_name/items (set by Fan Out Processes) don't survive that,
// so they're read back from Loop Over Processes' own loop output for this iteration.
const base = $json;
const source = $('Loop Over Processes').item.json;
return [{ json: { ...base, path: source.path, process_name: source.process_name, items: source.items } }];

// Execute Workflow silently drops every item but the first when given several -- bundles
// the N resolved (or failed) entries into a single `intents` array on ONE item so it
// survives the Context Update -> Router boundary intact. error/error_message are also
// mirrored at root from the first intent, purely so the shared Error Parser (which reads
// error/error_message off the root, same as everywhere else in this project) can classify
// a form-filling resolution failure without a separate lifting step.
const items = $input.all().map((it) => it.json);
const raw = items[0] || {};
const { path, process_name, process_definition, error, error_message, items: entryItems, ...sharedContext } = raw;
const intents = items.map((it) => ({
  path: it.path,
  process_name: it.process_name,
  process_definition: it.process_definition || null,
  error: it.error || null,
  error_message: it.error_message || null,
  items: it.items || [],
}));
return [{ json: { ...sharedContext, intents, error: intents[0]?.error ?? null, error_message: intents[0]?.error_message ?? null } }];

// Adapts this file's intents[0] shape into the generic Register Node contract --
// intents/error/error_message are consumed here (not spread through), same one-shot-signal
// convention this node always followed; new_process_parent_id is also consumed here rather
// than by Register Node itself, since only this caller knows what it means.
const { intents, error, error_message, new_process_parent_id, ...base } = $json;
const intent = intents[0] || {};
return [{ json: {
  ...base,
  process_definition: intent.process_definition,
  parent_id: new_process_parent_id ?? null,
  form_state: {},
  status: 'active',
  set_active: true,
} }];

// One-shot, multi-record variant of Agent: Form's own field-mapping/GET-filter extraction
// rules (see sap-process-form-filling.json) -- batch never gets a follow-up turn, and may
// need N records identified from one message/file set instead of Agent: Form's always-one.
// Runs once per process inside Loop Over Processes' own per-process loop, gated by
// Needs Batch Extraction? so single-match/general_inquiry turns never pay for it.
const data = $json;
const method = (data.process_definition?.api?.method || 'POST').toUpperCase();
const isGet = method === 'GET';
const files = (data.extracted_files || []).map((f) => `File ${f.bucket_file_id}:\n${f.extracted_content || '(no content)'}`).join('\n\n');

let schemaSection;
if (isGet) {
  const queryDef = data.process_definition?.query || {};
  const keyDef = queryDef.key || null;
  const filters = queryDef.filters || [];
  const filterLines = filters.map((f) => {
    const allowedOps = Array.isArray(f.operator) ? f.operator : [f.operator];
    return `  - ${f.id} (${f.label}, ${f.type})${allowedOps.length > 1 ? ` -- allowed operators: ${allowedOps.join(', ')}` : ''}`;
  });
  const keySection = keyDef
    ? `\nKEY (set key_value ONLY if the message names one specific record by this field; otherwise leave it null and use FILTERS below instead):\n  - ${keyDef.id} (${keyDef.sap_field})`
    : '';
  schemaSection = `This is a SEARCH/QUERY process -- always produce exactly ONE record.\n\nFILTERS AVAILABLE FOR THIS SEARCH:\n${filterLines.length ? filterLines.join('\n') : '  (none declared)'}${keySection}`;
} else {
  schemaSection = `This is a CREATE process -- identify every separate record the message/files describe.\n\nSCHEMA:\n\`\`\`json\n${JSON.stringify(data.process_definition?.form || {}, null, 2)}\n\`\`\``;
}

const chatInput = `Today: ${data.current_date}. Respond in: ${data.language}.

PROCESS: ${data.process_name}

${schemaSection}

USER MESSAGE:
${data.message}

ATTACHED FILE CONTENT:
${files || '(none)'}`;
return [{ json: { ...data, chatInput } }];

// Agent: Extract Batch Records returns raw text (same convention as Agent: Form/Agent: Find),
// not a structured-parser object -- parse it here, same fenced-code-block fallback used
// throughout this codebase. A one-shot extraction with nothing meaningful to retry against
// treats unparseable output the same as a genuine agent/tool crash -- surfaced via this
// intent's own error/error_message, the exact same channel a schema-resolution failure
// already uses (see Has Resolution Error? downstream in Batch Processing -- no new
// error-handling mechanism needed).
const base = $('Prompt: Extract Batch Records').first().json;
const current = $json;
if (current.error) {
  return [{ json: { ...base, error: 'AGENT_ERROR', error_message: current.error?.message || current.error } }];
}
const raw = current.output || '';
let parsed = null;
try {
  parsed = JSON.parse(raw.trim());
} catch {
  try {
    const stripped = raw.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
    parsed = JSON.parse(stripped);
  } catch {
    parsed = null;
  }
}
if (parsed === null || !Array.isArray(parsed.records)) {
  return [{ json: { ...base, error: 'AGENT_ERROR', error_message: 'Model output is not valid JSON' } }];
}
return [{ json: { ...base, items: parsed.records } }];
